DB="$HOME/.hermes/kanban/boards/scrum-poker/kanban.db"

apply() {
  local id="$1" body="$2"
  sqlite3 "$DB" ".timeout 8000" "BEGIN IMMEDIATE; UPDATE tasks SET body='$(printf '%s' "$body" | sed "s/'/''/g")' WHERE id='$id'; COMMIT;" >/dev/null 2>&1
  echo "updated $id"
}

